spec fn side_ok(w: u64, h: u64) -> bool { w <= 4000000000 && h <= 4000000000 }

spec fn is_area(w: u64, h: u64, r: u64) -> bool { r == w * h }

#[effects(pure)]
#[uses(side_ok, is_area)]
fn area(w: u64, h: u64) -> (r: u64)
    requires side_ok(w, h),
    ensures is_area(w, h, r),
{
    0
}

